from record import add,save
add('chapter-17','壓縮與加速也分開看，硬體是否受益要量實際後端。','章導覽承諾儲存/誤差/運算/行為四個不同問題，沒有把低bit當作整體速度保證。','需要由byte先建立表示成本，再走到PTQ/QAT及任務結果。',['導覽與17.1—17.15實際內容相符；不要求導覽完整量化算法。'])
add('17.1','FP32每格32bit，即4byte；FP16每格2byte；int8每格1byte。','2048元素×4/2/1=8192/4096/2048，形狀不變；全零to(int8)只隔離容器容量，不是一般量化。','減少每格儲存而不減參數；正文另交代scale、檔案metadata、cache與訓練額外成本。',['手算2048與8192/4096/2048一致。','quantization.json回查FP32 tensor566272/file588358、packed4 tensor168736/file182277、packed8 tensor226336/file242085；分拆115200低位元係數、25728非量化參數、640bias、1416scales可重算數值payload。'],unverified=['原始GPU記錄欄位已核；未下載私有權重實量file，不等同重訓。','網站桌面/手機版面未驗。'])
add('17.2','沒有截斷時最近格誤差不超過半格，超過範圍後則可能更大。','除scale、最近偶数round、clamp、int8、乘scale的各邊界明確，-128未用。','需要scale讓整數碼保留浮點範圍關係；細格改善本例誤差但縮小可涵蓋範圍。',['逐值手算[-1,0,1,2]→[-.5,0,.5,1]，scale.25碼[-3,1,3,5]；圖實際已看數值方向一致。'])
add('17.3','公式是`輸出差 = x @ (w−restored).T`。輸入的大小與方向都會影響誤差','權重誤差經輸入乘加，兩列誤差可相加或抵消，MAE不構成輸出上界。','需要區分單格壓縮誤差與完整任務品質，避免權重MAE等同答案保証。',['手算[1,1]輸出差[.4,0]、[1,-1]差[0,-.4]；x×10非零差±4，權重MAE不變。'])
add('17.4','保存碼之後，還原公式是`(碼−zero)×scale`。','範圍[-1,2]共15間隔scale.2、zero5，uint8只佔碼0—15而未打包；與signed-int4加8格式分開。','zero-point使浮點零在不對稱範圍有自己的碼；不能把碼0當所有格式的浮點零。',['[0,5,10,15]→[-1,0,1,2]；練習[-2,0,1]zero10、碼[0,10,15]；源碼quantize_affine含全零保護，而本例已明說非零寬度。'])
add('17.5','全表共用刻度要容納80，所以scale約11.4286。小列除以它全靠近0，四項會一起消失。','per_channel依最後軸求每輸出列scale，分組範圍與額外scale數清楚。','需要避免大列極值抹掉小列差異，且交代精度換附帶成本。',['源碼quantize_symmetric per_channel最後維amax支持敘述；手算全表小列MAE.0425，逐列碼[1,3,4,7]MAE.0025，大列MAE2.5，scale4→8bytes。'])
add('17.6','限制數值範圍與真正打包是兩步，scale也尚未加進理想碼大小。','33項4bit132bit需ceil/8=17bytes但回傳int8仍33bytes；qmax127/7對應刻度與半格誤差。','需要看精度/容器不同改動；不把範圍限制當已節省實際byte。',['算例8bit最大差.003937、4bit.071429為半格；源碼回傳int8、bits4/8與qmax一致。','格上arange(-7,8)/7的例外不夸大「每格必更差」。'])
add('17.7','**存成整數與用整數乘法是不同的事**，輸入和輸出在這裏都還是FP32。','QuantizedLinear保存packed uint8+per-row scale、forward重建float權重做F.linear；buffers不是普通可更新權重。','weight-only入門避免同時估activation範圍，儲存/運算/續訓介面不混。',['源碼QuantizedLinear.forward與storage_bytes讀取；4係數packed2bytes+2scale8bytes=10；bits8=12；手算輸出[.9,.5143]。','quantization.json回查packed4三版同FP32來源、先reload再評估；本頁沒有聲稱整數kernel。'])
add('17.8','第一碼放低四位，第二碼放高四位。例子−8、−1變碼0、7，byte是`0111 0000`','加8/low|high<<4與&15/>>4再減8互逆；odd長度补零碼8後依原shape裁掉。','需要真正把兩個4bit碼放一byte，且保留還原格式與原項數。',['源碼pack_int4/unpack_int4完整核對；7數碼[112,152,175,139]4bytes；增4後末203仍4bytes。','已直接看640bit圖，-8/-1、112與低高拆回順序一致。'])
add('17.9','要隔離轉換造成的差別，原版與量化版必須來自同一份數字。','deepcopy再replace避免原版被就地修改；eval/no_grad/tied=False及僅Linear替換邊界明確。','PTQ不更新權重，固定同源才能歸因精度轉換；隨機例只核介面。',['源碼replace_linear_layers就地setattr、未保留tie，此頁已明說需另設計；TinyLM默认264，3tokenlogits[1,3,264]。','原始quantization報告same_fp32_source/reload flags為真；未把隨機例當品質證明。'])
add('17.10','低位元來源不會讓普通乘法自動變成低位元計算。','FP32有8320bytes；4bitpacked1024+scale128+bias128=1280，但forward另重建8192byte權重。','需要分開檔案、載入峰、prefill/decode與backend；專用kernel用途交代但不保證硬體全受益。',['源碼參數與buffers計數一致；quantization.json fixed46prompt/8decode×3rep，FP32prefill2.4048ms、packed4 4.9582、packed8 2.7684；ms/token2.3713/4.8815/2.8138；原文限制co-residentbaseline與小形狀，無不當速度外推。'],unverified=['原始L4結果欄位核對，未在本CPU重做GPU時間/載入峰；其他硬體、公開匯出檔未驗。','實际网页版面未验。'])
add('17.11','新增誤差不代表每項一定惡化，有時方向偶然抵消。','新增activation量化與weight-only比較只有x是否還原不同；float模擬不等同packed/kernel。','需要看到輸入範圍隨內容變動而新增誤差；不借weight-only實驗證明activation性能。',['手算reference[[.53,-.25],[-.25,1.93]]、x@qw MAE.19、qx@qw MAE.24；非對角偶然恢復；qat.json activation_quantization=false吻合限定。'])
add('17.12','固定先前範圍，3會被截到1；按當次輸入重選範圍，又會把刻度變粗。','校準/固定與動態以何時決定activation範圍區分，非API普遍定義；未更新權重。','需要面對新輸入越界與粗格取捨，代表性校準資料/獨立測試用途具體。',['手算static范围max1 scale1/7時3→1誤差2；dynamic max3 scale3/7覆蓋3但格更粗；程式無optimizer。'])
add('17.13','誤差必須對原x計算，不能只比截斷後來源。','clamp到1後scale1/7，smallMAE下降但outlier99誤差在全MAE保留。','需要判斷outlier是噪音或有效信號，不能以小值改善直接決定門檻。',['手算未clipped小MAE.2全.15、clipped小.038095全24.77857與正文一致；最後考卷不參與挑選之限制明確。'])
add('17.14','反向刻意近似成直接通過，叫**直通估計（STE）**。它不是round真正的導數。','x+(restored-x).detach前向還原、反向identity，单向量无step；完整QAT浮點主權重+fakeforward後另打包。','需要round梯度0問題的近似學路，且設計目的只嘗試適應誤差不保證更好。',['frozen fake_quantize與_QATLinear規則實讀；STE sum梯度1與plain round0可由detach圖核。','qat.json相同init/batchplan、各350updates/39348targets、alpha之外不涉蒸餾；matchedPTQ6/10NLL.4066、QATpacked4/10NLL.5979；valid2/5same、NLL次序不同；fake/deployedlogit0及activation=false吻合。','實看640QAT流程圖，floatmaster/STE/step/pack與單例無更新的標示一致。'],unverified=['原始紀錄支持本次weight-only對照；未獨立下載教師/部署檔驗SHA及重訓；未查其他QAT配方或跨seed。','網站桌面/手機版面未验。'])
add('17.15','平均絕對差僅`(0.01+0)/2=0.005`，卻跨過了第一名邊界。','argmax邊界可被小logit改動跨過，EOS使後續生成路徑改；MAE與EM/NLL/EOS各有界限。','需要重新驗收自生成與任務子類，不能由均值小推論答案保留。',['兩候選手算1.005勝1→1.01勝1.005即EOS；quantization.json三版test6/10但NLL.4565/.4278/.4554與逐題不同；qat.json red:square:high本例普通packed square/QATcircle；標示未據此宣稱全任務不變。'])
